import { unstable_noStore as noStore } from 'next/cache'

let productStore = [
  { id: 1, name: 'Laptop', price: 999 },
  { id: 2, name: 'Phone', price: 699 },
  { id: 3, name: 'Tablet', price: 499 },
  { id: 4, name: 'Headphones', price: 199 },
  { id: 5, name: 'Watch', price: 299 },
]

export async function getAllProducts() {
  noStore()

  await new Promise((resolve) => setTimeout(resolve, 1200))

  return productStore
}

export async function syncProducts() {
  await new Promise((resolve) => setTimeout(resolve, 800))

  const variants = ['Pro', 'Max', 'Ultra', 'Lite', 'X']
  const delta = Math.floor(Math.random() * 200) - 100

  productStore = productStore.map((p) => ({
    ...p,
    name: `${p.name.split(' ')[0]} ${variants[Math.floor(Math.random() * variants.length)]}`,
    price: Math.max(49, p.price + delta + Math.floor(Math.random() * 100)),
  }))
}

